async function complete(role:string,value:unknown){const turn=lastTurn(role);if(role==='orchestrator'&&value&&typeof value==='object'&&'write_scope'in(value as object)){const task=modules.state.getState().tasks.find((row:any)=>row.orchestratorThreadId===turn.threadId);const selected=modules.state.getTask(task?.id)?.passes?.find((pass:any)=>pass.id===task?.currentPassId)?.selectedSkills||[];await recruit([{...workerPlan(),assignment:value as typeof assignment,skill_refs:selected.map((skill:any)=>skill.id)}]);return turn;}if(role==='worker'){fake.dshSessions.get(turn.threadId)?.complete(turn.turnId,value);return turn;}const owner=fake.threadOwners.get(turn.threadId)||fake.instance;owner.emit('notification','turn/completed',{threadId:turn.threadId,turn:{id:turn.turnId,status:'completed',items:[{type:'agentMessage',text:JSON.stringify(value)}]}});return turn;}
async function waitForRole(role:string){await waitFor(()=>fake.calls.some(row=>row.kind==='turn'&&row.role===role));const turn=lastTurn(role);await waitFor(()=>role==='worker'?isActiveWorkerTurn(turn.threadId):modules?.state.getState().tasks.some((task:any)=>task[`${role}ThreadId` as string]===turn.threadId&&task.activeTurnId===turn.turnId));return turn;}
function workerPlan(overrides:Partial<Assignment>={},effort:'max'='max',skill_refs:string[]=[]){return {name:'Implementation worker',step:'Implement the bounded requested change',depends_on:[] as string[],assignment:{...assignment,...overrides},effort,skill_refs};}
type WorkerPlan=ReturnType<typeof workerPlan>;
function sendRecruitmentRequest(id:string,workers:WorkerPlan[]){const turn=lastTurn('orchestrator'),owner=fake.threadOwners.get(turn.threadId)||fake.agentInstance;owner.emit('serverRequest',id,'item/tool/call',{threadId:turn.threadId,turnId:turn.turnId,namespace:'pseudoharness',tool:'recruit_workers',arguments:{workers}});return turn;}
async function recruit(workers:WorkerPlan[]=[workerPlan({write_scope:[path.join(projectRoot,'src')]})]){const taskId=modules?.state.getState().activeTaskId;const beforePass=modules?.state.getTask(taskId)?.passes?.find((pass:any)=>pass.id===modules.state.getTask(taskId)?.currentPassId);const beforeTeamId=beforePass?.recruitmentTeam?.teamId;const workerTurnsBefore=turns('worker').length;const turn=lastTurn('orchestrator');const owner=fake.threadOwners.get(turn.threadId)||fake.agentInstance;const id=`recruit-${fake.turnCount}`;owner.emit('serverRequest',id,'item/tool/call',{threadId:turn.threadId,turnId:turn.turnId,namespace:'pseudoharness',tool:'recruit_workers',arguments:{workers}});await waitFor(()=>fake.calls.some(row=>row.kind==='server-response'&&row.id===id));const response=fake.calls.find(row=>row.kind==='server-response'&&row.id===id)?.result;if(response?.success!==true)throw new Error(`Recruitment fixture rejected: ${response?.contentItems?.[0]?.text||JSON.stringify(response)}`);owner.emit('notification','turn/completed',{threadId:turn.threadId,turn:{id:turn.turnId,status:'completed',items:[{type:'agentMessage',text:'The complete team is sealed; I will wait for the combined receipt.'}]}});await waitFor(()=>{const pass=modules?.state.getTask(taskId)?.passes?.find((row:any)=>row.id===beforePass?.id),team=pass?.recruitmentTeam;return !!team?.sealed&&team.teamId!==beforeTeamId&&team.workers.length===workers.length;});await waitFor(()=>turns('worker').length>workerTurnsBefore||modules?.state.getTask(taskId)?.passes?.some((pass:any)=>pass.recruitmentTeam?.workers.some((worker:any)=>['failed','blocked'].includes(worker.status))));const currentTeam=modules?.state.getTask(taskId)?.passes?.find((pass:any)=>pass.id===beforePass?.id)?.recruitmentTeam;const failed=currentTeam?.workers.find((worker:any)=>['failed','blocked'].includes(worker.status));if(failed)throw new Error(`Recruited worker did not start: ${failed.error||failed.status}`);return lastTurn('worker');}
async function runRecruitedTeamToReview(workerReceiptValue:unknown,integrationReceiptValue:unknown,qaEnabled=false,options:{beforeStart?:()=>void;until?:'review'|'audit-starting'|'audit-needs-attention';stateMutationGate?:StateMutationGate}={}){
  const {orchestrator,state}=await setup(true,undefined,options.stateMutationGate,'deepseek');options.beforeStart?.();const task=await orchestrator.submitTask('Add one bounded feature with a recruited worker and integration receipt.',undefined,[],[],undefined,undefined,qaEnabled);await state.mutate((saved:any)=>{saved.settings.executionProfile={provider:'codex',model:'gpt-6-luna',effort:'max'};});await complete('router',{route:'hard_task',rule_id:'hard_new_feature',justification:'This request introduces behavior.'});await waitForRole('orchestrator');await recruit([workerPlan({...assignment,write_scope:[path.join(projectRoot,'src')]})]);
  await waitFor(()=>turns('worker').length===1&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:workerReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
  await waitFor(()=>state.getTask(task.id)?.passes?.[0]?.recruitmentTeam?.integration.status==='running');await waitFor(()=>turns('worker').length===2&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:integrationReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
  if(options.until==='audit-starting')await waitFor(()=>state.getTask(task.id)?.passes?.[0]?.qualityLoop?.status==='auditing'&&['starting','auditing'].includes(state.getTask(task.id)?.passes?.[0]?.qualityLoop?.rounds.at(-1)?.status||''));
  else if(options.until==='audit-needs-attention')await waitFor(()=>state.getTask(task.id)?.passes?.[0]?.qualityLoop?.status==='needs_attention'&&state.getTask(task.id)?.passes?.[0]?.qualityLoop?.resumeAction==='audit');
  else await waitFor(()=>turns('orchestrator').length===2&&state.getTask(task.id)?.phase==='reviewing');return {orchestrator,state,task};
}
async function saveAndPauseQaFinding(context:any,title:string){
  let pausePromise:Promise<unknown>|undefined,paused=false;const unsubscribe=context.state.subscribe((snapshot:any)=>{const task=snapshot.tasks.find((row:any)=>row.id===context.task.id),loop=task?.passes?.find((row:any)=>row.id===task.currentPassId)?.qualityLoop;if(!paused&&loop?.status==='awaiting_corrections'&&loop.rounds.at(-1)?.status==='awaiting_corrections'){paused=true;pausePromise=context.orchestrator.pauseQualityLoop(context.task.id);}});
  try{await complete('orchestrator',{type:'qa_audit',status:'issues_found',summary:'A saved QA finding needs one correction.',findings:[{title,severity:'medium',issue:'The behavior is not preserved.',required_fix:'Correct the behavior and add a regression.',evidence:['Observed during the focused QA audit.'],file:'src/example.ts',line:2}]});await waitFor(()=>paused&&context.state.getTask(context.task.id)?.passes?.[0]?.qualityLoop?.status==='paused');if(pausePromise)await pausePromise;}finally{unsubscribe();}
  const pass=context.state.getTask(context.task.id)?.passes?.find((row:any)=>row.id===context.state.getTask(context.task.id)?.currentPassId),round=pass?.qualityLoop?.rounds.at(-1);if(!pass||!round)throw new Error('The QA finding was not saved.');return {passId:pass.id,roundId:round.roundId,integrationHead:round.integrationHead,findings:round.findings};
}
async function completeCurrentSingleWorkerTeam(workerReceiptValue:unknown,integrationReceiptValue:unknown){
  const initial=turns('worker').length-1;
  await waitFor(()=>turns('worker').length>=initial+1&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:workerReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
  await waitFor(()=>turns('worker').length>=initial+2&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:integrationReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
}
